{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "An immigration officer is defined as a state, local, or federal law enforcement officer seeking to enforce immigration law, including specified federal officers.",
      "rationale": "Conveys the complete operative definition. Naming the illustrative federal agencies is not necessary to convey its scope."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill would require the director of a local education agency (LEA) or public charter school to immediately notify all enrolled students, their parents, and the school’s educators, employees, and contractors whenever an immigration officer is on the grounds of a public school controlled by the LEA or of the public charter school.",
      "rationale": "Identifies the responsible directors, immediate notification duty, recipients, and triggering presence on the specified school grounds."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "The bill would also state that this notice requirement and related school policies are not sanctuary policies and would shield the listed school officials and employees from penalties under the cited statutes for adopting or enforcing a sanctuary policy.",
      "rationale": "Conveys the sanctuary-policy exclusion and penalty protection, but does not identify board and governing-body members as protected. It also describes policies only as related, rather than policies adopted by the local board or charter governing body to effectuate the section."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law.",
      "rationale": "States the effective-date trigger accurately."
    }
  ]
}
